SELECT CASE WHEN duration_sec >= 407 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, DATE_TRUNC('WEEK', event_time) AS week_start, COUNT(*) FILTER (WHERE page = '/home') AS home_rows, SUM(duration_sec) FILTER (WHERE page = '/home') AS home_total_duration_sec, MAX(event_time) AS ended_at FROM web_events GROUP BY duration_sec_tier, week_start HAVING home_total_duration_sec >= 0;
